<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Note;
use App\Models\KnowledgeFolder;
use App\Models\Workspace;
use App\Services\Identity;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Storage;
use Tests\TestCase;
class KnowledgeTest extends TestCase {
 use RefreshDatabase;
 private function login(User $u): static{return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version])->withoutVite();}
 private function data(array $extra=[]): array{return array_merge(['title'=>'Research note','kind'=>'note','body'=>'# Heading','tags'=>'linux, php','archived'=>0],$extra);}
 private function note(User $u,array $extra=[]): Note{$n=new Note(array_merge(['title'=>'Private note','kind'=>'note','body'=>'Private body','tags'=>[],'archived'=>false],$extra));$n->workspace_id=Identity::personal($u)->id;$n->version=1;$n->save();return $n;}
 public function test_guests_denied(): void{$this->get('/knowledge')->assertRedirect('/login');}
 public function test_crud_revision_and_stale_update(): void{$u=User::factory()->create();$this->login($u)->post('/knowledge',$this->data())->assertRedirect();$n=Note::firstOrFail();$this->get('/knowledge/'.$n->id)->assertOk()->assertSee('<h1>Heading</h1>',false);$this->get('/knowledge/create')->assertOk();$this->get('/knowledge/'.$n->id.'/edit')->assertOk();$this->put('/knowledge/'.$n->id,$this->data(['version'=>1,'body'=>'Updated']))->assertRedirect();$this->assertSame(2,$n->fresh()->version);$this->assertSame('# Heading',$n->revisions()->firstOrFail()->snapshot['body']);$this->put('/knowledge/'.$n->id,$this->data(['version'=>1]))->assertSessionHasErrors('version');$this->delete('/knowledge/'.$n->id)->assertRedirect();$this->assertDatabaseMissing('notes',['id'=>$n->id]);}
 public function test_types_and_bookmark_validation(): void{$u=User::factory()->create();$this->login($u);foreach(Note::KINDS as $kind)$this->post('/knowledge',$this->data(['kind'=>$kind,'url'=>'https://example.org','journal_date'=>'2026-11-27']))->assertRedirect();$this->assertSame(8,Note::count());$this->post('/knowledge',$this->data(['kind'=>'bookmark','url'=>'javascript:alert(1)']))->assertSessionHasErrors('url');$this->post('/knowledge',$this->data(['kind'=>'journal']))->assertSessionHasErrors('journal_date');}
 public function test_folder_tags_search_and_archive(): void{$u=User::factory()->create();$this->login($u)->post('/knowledge/folders',['name'=>'Learning'])->assertRedirect();$f=KnowledgeFolder::firstOrFail();$this->post('/knowledge',$this->data(['folder_id'=>$f->id,'body'=>'Unique query text']))->assertRedirect();$n=Note::firstOrFail();$this->get('/knowledge?q=Unique&tag=linux&folder_id='.$f->id)->assertOk()->assertSee('Research note');$this->put('/knowledge/'.$n->id,$this->data(['version'=>1,'archived'=>1]))->assertRedirect();$this->get('/knowledge')->assertOk()->assertDontSee('Research note');$this->get('/knowledge?archived=1')->assertOk()->assertSee('Research note');}
 public function test_backlinks_and_scoped_links(): void{$u=User::factory()->create();$other=User::factory()->create();$a=$this->note($u,['title'=>'Source note']);$b=$this->note($u,['title'=>'Target note']);$foreign=$this->note($other);$this->login($u)->put('/knowledge/'.$a->id,$this->data(['title'=>'Source note','version'=>1,'links'=>[$b->id]]))->assertRedirect();$this->get('/knowledge/'.$b->id)->assertOk()->assertSee('Source note');$this->put('/knowledge/'.$a->id,$this->data(['version'=>2,'links'=>[$foreign->id]]))->assertSessionHasErrors('links');$this->put('/knowledge/'.$a->id,$this->data(['version'=>2,'links'=>[$a->id]]))->assertSessionHasErrors('links');}
 public function test_foreign_note_search_export_and_mutations_denied(): void{$u=User::factory()->create();$other=User::factory()->create();$n=$this->note($other,['title'=>'Hidden private title']);Identity::personal($other)->members()->attach($u->id,['role'=>'admin']);$this->login($u)->get('/knowledge?q=Hidden')->assertOk()->assertDontSee('Hidden private title');foreach(['/knowledge/'.$n->id,'/knowledge/'.$n->id.'/edit','/knowledge/'.$n->id.'/export'] as $url)$this->get($url)->assertNotFound();$this->put('/knowledge/'.$n->id,$this->data(['version'=>1]))->assertNotFound();$this->delete('/knowledge/'.$n->id)->assertNotFound();$this->get('/dashboard')->assertOk()->assertDontSee('Hidden private title');}
 public function test_business_context_denied(): void{$u=User::factory()->create();$w=Workspace::create(['owner_id'=>$u->id,'name'=>'Business','type'=>'business']);$this->login($u)->withSession(['workspace_id'=>$w->id])->get('/knowledge')->assertForbidden();}
 public function test_safe_markdown_and_private_cache(): void{$u=User::factory()->create();$n=$this->note($u,['body'=>'<script>alert(1)</script>'.chr(10).chr(10).'![remote](https://example.org/pixel.png)'.chr(10).'[click](javascript:alert(1))']);$this->login($u)->get('/knowledge/'.$n->id)->assertOk()->assertDontSee('<script>alert(1)</script>',false)->assertDontSee('https://example.org/pixel.png',false)->assertDontSee('href="javascript:',false)->assertHeader('Cache-Control','no-store, private');}
 public function test_private_attachments_and_delete_guard(): void{Storage::fake('local');$u=User::factory()->create();$n=$this->note($u);$other=$this->note(User::factory()->create());$this->login($u)->post('/knowledge/'.$n->id.'/attachments',['file'=>UploadedFile::fake()->createWithContent('readme.txt','safe text')])->assertRedirect();$a=$n->attachments()->firstOrFail();Storage::disk('local')->assertExists($a->path);$this->get('/knowledge/'.$n->id.'/attachments/'.$a->id)->assertOk()->assertDownload('readme.txt');$this->get('/knowledge/'.$other->id.'/attachments/'.$a->id)->assertNotFound();$this->delete('/knowledge/'.$n->id)->assertSessionHasErrors('note');$this->post('/knowledge/'.$n->id.'/attachments',['file'=>UploadedFile::fake()->createWithContent('bad.php','<?php echo 1;')])->assertSessionHasErrors('file');$this->delete('/knowledge/'.$n->id.'/attachments/'.$a->id)->assertRedirect();Storage::disk('local')->assertMissing($a->path);}
 public function test_export_and_foreign_folder_validation(): void{$u=User::factory()->create();$other=User::factory()->create();$f=new KnowledgeFolder(['name'=>'Foreign']);$f->workspace_id=Identity::personal($other)->id;$f->save();$n=$this->note($u);$this->login($u)->post('/knowledge',$this->data(['folder_id'=>$f->id]))->assertSessionHasErrors('folder_id');$r=$this->get('/knowledge/'.$n->id.'/export')->assertOk()->assertDownload('note-'.$n->id.'.json');$this->assertSame('Private body',json_decode($r->streamedContent(),true)['body']);}
 public function test_markdown_preserves_unicode_and_removes_external_elements(): void{$u=User::factory()->create();$n=$this->note($u,['body'=>"## বাংলা".chr(10).chr(10)."**bold** [label](https://example.org) ![image](https://example.org/pixel)".chr(10).chr(10).'<h2 onclick="alert(1)">Unsafe</h2>']);$html=app(\App\Services\KnowledgeService::class)->render($n);$this->assertStringContainsString('<h2>বাংলা</h2>',$html);$this->assertStringContainsString('<strong>bold</strong>',$html);$this->assertStringNotContainsString('onclick=',$html);$this->assertStringNotContainsString('https://example.org',$html);$this->assertStringNotContainsString('<img',$html);}
 public function test_existing_link_outside_picker_limit_remains_selectable(): void{$u=User::factory()->create();$source=$this->note($u,['title'=>'Source']);$target=$this->note($u,['title'=>'ZZZ retained link']);$source->links()->attach($target->id);$rows=[];for($i=0;$i<200;$i++)$rows[]=['workspace_id'=>$source->workspace_id,'title'=>'A '.str_pad((string)$i,3,'0',STR_PAD_LEFT),'kind'=>'note','body'=>'','tags'=>'[]','archived'=>false,'version'=>1,'created_at'=>now(),'updated_at'=>now()];Note::insert($rows);$this->login($u)->get('/knowledge/'.$source->id.'/edit')->assertOk()->assertSee('ZZZ retained link');}
 public function test_attachment_mismatched_parent_denied_within_workspace(): void{Storage::fake('local');$u=User::factory()->create();$a=$this->note($u);$b=$this->note($u);$this->login($u)->post('/knowledge/'.$a->id.'/attachments',['file'=>UploadedFile::fake()->createWithContent('readme.txt','safe text')])->assertRedirect();$file=$a->attachments()->firstOrFail();$this->get('/knowledge/'.$b->id.'/attachments/'.$file->id)->assertNotFound();$this->delete('/knowledge/'.$b->id.'/attachments/'.$file->id)->assertNotFound();Storage::disk('local')->assertExists($file->path);}

}
